import { z } from "zod"

// data/models.ts — a curated, DATED snapshot of frontier + notable LLMs for the
// /models comparison page. A snapshot, not a live feed: leaderboards churn.
//
// Method (snapshot 2026-10-08): every model Artificial Analysis lists was read
// from its leaderboard page (artificialanalysis.ai/leaderboards/models, the
// per-model records embedded in its Next.js payload), all from that one page
// on one day. Field mapping, unchanged since the July snapshot:
//   intelligence = intelligenceIndex, AA Intelligence Index v4.3.2 (AA moved
//                  from v4.3 to v4.3.2 since September: re-fitted pairwise Elo
//                  for GDPval-AA and AA-Briefcase, judge panels refreshed; all
//                  AA-listed values below were re-read, none is carried over)
//   priceIn/Out  = price1mInputTokens / price1mOutputTokens (USD per 1M tokens)
//   speedTps     = medianOutputTokensPerSecond
//   latencyS     = medianTimeToFirstTokenSeconds (first token of any kind, so
//                  reasoning tokens count; Haiku 4.5's reasoning variant is 15.18
//                  here, and 0.50 for its non-reasoning one)
//   contextK     = contextWindowTokens / 1000, rounded
// A model is shown as AA's highest-effort reasoning variant (max, else xhigh,
// high, plain "Reasoning", medium), which is what the July snapshot used where
// that can be checked (Haiku 4.5, above); `note` names the variant and flags
// scores AA marks as estimated. A field AA has no value for is null,
// except list prices already sourced in July, which are kept and say so.
// `released` is AA's release date where the record had none. Models AA does not
// list come from llm-stats (api.zeroeval.com), provider docs, Hugging Face and
// this site's articles, and carry no AA-measured fields. Per-model sources are
// in data/models-sources.md. `eci` is Epoch's Capabilities Index, read from
// eci_scores.csv in epoch.ai/data/benchmark_data.zip on the same day, where
// Epoch scores the same model version. Any value that isn't sourced is `null`,
// never guessed — the UI renders around missing data.
// Blended price follows AA's 3:1 input:output convention.

export const MODELS_SNAPSHOT_DATE = "2026-10-08"
export const MODELS_INDEX_VERSION = "v4.3.2"

export type Origin = "US" | "China" | "EU" | "Canada" | "UAE" | "Korea" | "Israel" | "India" | "Other"

export type ModelRecord = {
  name: string
  provider: string
  origin: Origin
  openWeights: boolean
  sizeB: number | null
  intelligence: number | null
  eci: number | null
  priceIn: number | null
  priceOut: number | null
  speedTps: number | null
  latencyS: number | null
  contextK: number | null
  released: string | null
  article?: string
  note?: string
}

export function blendedPrice(m: ModelRecord): number | null {
  if (m.priceIn == null || m.priceOut == null) return null
  return Math.round(((m.priceIn * 3 + m.priceOut) / 4) * 1000) / 1000
}

// Context window label: AA reports exact token counts, so 1,048,576 tokens is
// contextK 1049; show it as "1.05M", not "1.049M".
export function contextLabel(k: number): string {
  return k >= 1000 ? `${Math.round(k / 10) / 100}M` : `${k}K`
}

